-- ==========================================================================
-- B4 FOLLOW-ON FIX (cashflow): cashflow: duplicate question rewritten into a new question
--
-- Courses: cashflow. Rows changed: 1; rows inserted: 0.
-- Source: tools/answer-length-audit/fixes/cashflow.json (every item, its verdict and
-- its reason, old and new text side by side); generated by
-- tools/answer-length-audit/fix.py sql cashflow. Runs AFTER the 29 B4 length files
-- and any earlier fix file: every guard below is the text those leave behind.
--
-- GUARDS. Each changed row must match its OLD prompt, explanation and options
-- (md5) and answer_index exactly (then it is updated) or its NEW ones (already
-- applied, left alone). Anything else raises and the transaction rolls back.
-- Each insert must be absent (inserted) or present with the same text (left).
-- Each course ends at its asserted question count. SAFE TO RE-RUN.
-- ==========================================================================

do $$
declare
  v_state   text;
  v_count   integer;
  v_updated integer := 0;
  v_total   integer;
begin

  -- cashflow advanced final - ord 13
  select case when md5(prompt) = '14a0749b01d00ef646322a7787323ebe' and md5(coalesce(explanation, '')) = 'eec6a33263af5514ea1674220d36b5bf' and md5(options::text) = md5('["The engine''s default, conservative_zero, which the course records as a finding of the extraction.", "The terrain string, which carries the reading with it and settles the rate once the terrain is entered.", "The owner of the discount rate, since the two readings differ only in the rate at which the HCT is discounted.", "Counsel; a ledger that reports one without the other has taken a legal position without saying so."]'::jsonb::text) and answer_index = 3 then 'old'
              when md5(prompt) = '0b3a27bf25f9c0ab8eb223f714f84934' and md5(coalesce(explanation, '')) = '5f1d0ed3b72d1e7ba736dfeea34ec75c' and md5(options::text) = md5('["That the price is the bigger lever, since a market move is worth more than any word in the fiscal terms.", "That the two moves are the same size, because deep offshore lowers only the royalty and a price rise lifts revenue by as much.", "That the terrain string is a price effect in disguise, since a lower royalty rate acts exactly like a higher realised price on every barrel.", "That a word in the document outweighs the market: the terrain string moves NPV further than the price sweep to 120."]'::jsonb::text) and answer_index = 3 then 'new'
              else 'other' end
    into v_state
    from public.academy_quiz_questions where app_slug = 'cashflow' and tier = 'advanced' and scope = 'final' and module_key is not distinct from null and ord = 13 and active;
  if v_state is null then raise exception 'B4 fix cashflow refused: no row for cashflow advanced final - ord 13'; end if;
  if v_state = 'other' then raise exception 'B4 fix cashflow refused: cashflow advanced final - ord 13 matches neither its current nor its fixed form'; end if;
  if v_state = 'old' then
    update public.academy_quiz_questions set prompt = 'AKATA under the PIA reports NPV 43223505.88 in shallow water, 128984232.18 at an oil price of 120, and 141623594.88 in deep offshore under the conservative reading. What does that comparison tell a negotiator?', options = '["That the price is the bigger lever, since a market move is worth more than any word in the fiscal terms.", "That the two moves are the same size, because deep offshore lowers only the royalty and a price rise lifts revenue by as much.", "That the terrain string is a price effect in disguise, since a lower royalty rate acts exactly like a higher realised price on every barrel.", "That a word in the document outweighs the market: the terrain string moves NPV further than the price sweep to 120."]'::jsonb,
           answer_index = 3, explanation = 'Deep offshore under the conservative reading lowers the production royalty rate and zeroes the HCT, which lifts NPV to 141623594.88, further than the 128984232.18 an oil price of 120 buys. A cap, a lease status or a reading moves NPV further than the market, and those are words in a document.'
     where app_slug = 'cashflow' and tier = 'advanced' and scope = 'final' and module_key is not distinct from null and ord = 13 and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'B4 fix cashflow refused: cashflow advanced final - ord 13 updated % rows', v_count; end if;
    v_updated := v_updated + 1;
  end if;

  select count(*) into v_total from public.academy_quiz_questions where app_slug = 'cashflow' and active;
  if v_total <> 396 then raise exception 'B4 fix cashflow refused: cashflow holds % active questions, expected 396', v_total; end if;
  raise notice 'B4 fix cashflow: % of 1 rows written, the rest already carried the fixed text', v_updated;
end $$;
